import type { AnchorHTMLAttributes, Dispatch, SetStateAction } from 'react';

import type {
  ButtonAria,
  AriaButtonProps,
} from '../../buttons/button/types/button-aria.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import type { OverlayTriggerState } from '../../overlays/hooks/useOverlay.js';
import type {
  UseOverlayWithTriggerProps,
  ModalAriaProps,
} from '../../overlays/hooks/useOverlayWithTrigger.js';
import { useOverlayWithTrigger } from '../../overlays/hooks/useOverlayWithTrigger.js';

/**
 * Uses useOverlayWithTrigger to create the overlay.
 *
 * @returns appropriate props to use
 */
export function useVisibilityOverlayWithTrigger(): {
  rootRef: (instance: HTMLButtonElement | null) => void;
  overlayRef: Dispatch<SetStateAction<HTMLElement | null>>;
  overlayState: OverlayTriggerState;
  overlayProps: ModalAriaProps & Pick<UseOverlayWithTriggerProps, 'trapFocus'>;
  overlayTriggerProps: ButtonAria<AnchorHTMLAttributes<HTMLButtonElement>> &
    AriaButtonProps;
} {
  const {
    targetRef,
    triggerRef,
    overlayRef,
    overlayState,
    overlayProps,
    overlayTriggerProps,
  } = useOverlayWithTrigger({
    placement: 'bottom-end',
    placementFallbacks: ['top-end', 'top-start', 'top-end', 'bottom-start'],
    offset: 4,
    widthStrategy: { min: 200 },
    heightStrategy: 'maxViewport',
  });

  const rootRef = useMergeRefs([triggerRef, targetRef]);

  return {
    rootRef,
    overlayRef,
    overlayState,
    overlayProps,
    overlayTriggerProps,
  };
}
